class Solution {
public:
    int badSensor(vector<int>& a,vector<int>& b) {
        int n=a.size(),i=0;
        while(i<n && a[i]==b[i])i++;
        if(i==n)return -1;
        bool x=true,y=true;
        for(int j=i;j<n-1;j++){
            if(a[j]!=b[j+1])x=false;
            if(b[j]!=a[j+1])y=false;
        }
        if(x==y)return -1;
        return x?1:2;
    }
};
